import re
from robot.api import logger


class EgateDispCommandsOutputParser(object):
    """

    """
    TABLE_REGEXP = re.compile(r'(\={3,})([\s\S]*?)(\={3,})')
    SKIP_LINES_REGEXP = re.compile(r'(\={2,})|(\-{2,})')
    SPLIT_TABLE_REGEXP = re.compile(r'(=+)(\s+)(=+)')

    def __init__(self, cmd_output, reg_exp=None, skip_line_regexp=None, findall=False):
        """

        :param cmd_output: Output returned by command on EGATE console
        :param reg_exp: Regexp to parse table from output
        :param skip_line_regexp:
        """
        self._table_regexp = reg_exp
        self._skip_line_regexp = skip_line_regexp
        self._cmd_output = cmd_output
        self._table_parsed_from_output = None
        self._columns_info = []
        self._table_rows = []
        self._parsed_lines = []

        if findall:
            tables = re.findall(EgateDispCommandsOutputParser.TABLE_REGEXP, self._cmd_output)
            for table in tables:
                self._cmd_output = ''.join(table)
                self._get_table_from_cmd_output()
                self._split_table_rows()
                self._save_columns_start_positions()
                self._parsed_lines.append(self._get_columns_headers())
                self._parsed_lines.extend(self._get_columns_values_for_row())
                self._columns_info = []
                self._table_rows = []
        else:
            self._get_table_from_cmd_output()
            self._split_table_rows()
            self._save_columns_start_positions()
            self._parsed_lines.append(self._get_columns_headers())
            self._parsed_lines.extend(self._get_columns_values_for_row())

    def get_list_of_output_parsed_lines(self):
        """

        :return:
        """
        logger.debug('{} - egate command output:\n{}\n'.format(self.__class__.__name__, self._table_parsed_from_output))
        return self._parsed_lines

    def parse_column_value_with_custom_function(self, column_name, parse_function):
        """

        :param column_name:
        :param parse_function:
        :return:
        """
        col_idx = self._parsed_lines[0].index(column_name)
        for line_idx, line in enumerate(self._parsed_lines):
            if column_name != line[col_idx]:
                self._parsed_lines[line_idx][col_idx] = parse_function(line[col_idx])

    def remove_row_with_value_in_column(self, column_name, column_value):
        """

        :param column_name:
        :param column_value:
        :return:
        """
        col_idx = self._parsed_lines[0].index(column_name)
        for line_idx, line in enumerate(self._parsed_lines):
            if column_value == line[col_idx]:
                del self._parsed_lines[line_idx]

    def _get_table_from_cmd_output(self):
        if re.search(EgateDispCommandsOutputParser.SPLIT_TABLE_REGEXP, self._cmd_output):
            self._format_cmd_output_table()
        if self._table_regexp:
            cmd_output_table = re.search(self._table_regexp, self._cmd_output)
        else:
            cmd_output_table = re.search(EgateDispCommandsOutputParser.TABLE_REGEXP, self._cmd_output)
        if cmd_output_table:
            self._table_parsed_from_output = cmd_output_table.group(0).rstrip('\n')

    def _format_cmd_output_table(self):
        temp_rows = self._cmd_output.split('\n')
        if temp_rows[-1] == '':
            temp_rows.pop()
        formatted_table = ''
        for i in range(0, len(temp_rows), 2):
            formatted_table += temp_rows[i] + temp_rows[i + 1] + '\n'
        self._cmd_output = formatted_table

    def _split_table_rows(self):
        self._table_rows = self._table_parsed_from_output.split('\n')
        self._skip_blank_lines()
        self._skip_lines()

    def _get_columns_headers(self):
        columns_headers_row = self._table_rows[0].rstrip()
        columns_headers_list = re.split(r'\s{2,}', columns_headers_row)
        return columns_headers_list

    def _skip_lines(self):
        for idx, row in enumerate(self._table_rows):
            if self._skip_line_regexp:
                skip_line = re.search(self._skip_line_regexp, row.rstrip())
            else:
                skip_line = re.search(EgateDispCommandsOutputParser.SKIP_LINES_REGEXP, row.rstrip())

            if skip_line:
                del self._table_rows[idx]

    def _skip_blank_lines(self):
        for idx, row in enumerate(self._table_rows):
            if not re.search(r'\S+', row):
                del self._table_rows[idx]

    def _save_columns_start_positions(self):
        columns_headers_list = self._get_columns_headers()
        columns_headers_row = self._table_rows[0]
        start_pos = 0
        for column in columns_headers_list:
            tmp = {}
            tmp['column_name'] = column
            tmp['starting_position'] = columns_headers_row[start_pos:].find(column) + start_pos
            start_pos = tmp['starting_position']
            self._columns_info.append(tmp)

    def _get_columns_values_for_row(self):
        parsed_rows = []
        table_data_rows = self._table_rows[1:]
        id = 0
        for row_data in table_data_rows:
            if row_data:
                row_data_values_list = self._parse_single_row(row_data)
                parsed_rows.append(row_data_values_list)
                id += 1
        return parsed_rows

    def _parse_single_row(self, row_data):
        row_data_values_list = []
        for idx, column_header in enumerate(self._columns_info):
            try:
                value_start = column_header['starting_position']
                value_end = self._columns_info[idx + 1]['starting_position']
                value = row_data[value_start:value_end].rstrip().lstrip()
                row_data_values_list.append(value)
            except IndexError:
                value_start = column_header['starting_position']
                value = row_data[value_start:].rstrip().lstrip()
                row_data_values_list.append(value)
        return row_data_values_list
